for n,chains in [(55,[('f(g(3))',[3,4,6]),('g(f(2))',[2,1,5]),('(f∘g)(5)',[5,3,5]),('(g∘f)(5)',[5,2,3])]),(56,[('g(g(g(2)))',[2,3,4,1]),('(f∘f∘f)(1)',[1,3,5,2]),('(f∘f∘g)(1)',[1,5,2,1]),('(g∘f∘g)(3)',[3,4,6,2])])]:
 add(n,('표 x=(1,2,3,4,5,6),f=(3,1,5,6,2,4),g=(5,3,4,1,3,2)를 사용해 '+', '.join('('+chr(97+i)+')'+q for i,(q,c)in enumerate(chains))+'를 구하라.','Use x=(1,2,3,4,5,6),f=(3,1,5,6,2,4),g=(5,3,4,1,3,2) to evaluate '+', '.join('('+chr(97+i)+')'+q for i,(q,c)in enumerate(chains))+'.'),[(q+': '+'→'.join(map(str,c)),q+': '+'→'.join(map(str,c)))for q,c in chains],(', '.join('('+chr(97+i)+')'+str(c[-1])for i,(q,c)in enumerate(chains)),', '.join('('+chr(97+i)+')'+str(c[-1])for i,(q,c)in enumerate(chains))),('각 화살표에서 바로 이전 출력으로 표의 입력 열을 다시 찾았다.','At each arrow,the preceding output is used to look up a new input column.'),list('abcd'))
add(57,('원본 빨강 f는(0,0)→(2,−2)→(6,6)의 선분, 파랑 g는 D=[−4,4]이며 g(−2)=1,g(0)=3,g(1)=4,g(2)=5,g(4)=3이다. (a)f(g(2)),(b)g(f(0)),(c)(f∘g)(0),(d)(g∘f)(6),(e)(g∘g)(−2),(f)(f∘f)(4)를 구하고 정의되지 않으면 이유를 밝혀라.','The red f joins(0,0)→(2,−2)→(6,6). The blue g has domain[−4,4],with g(−2)=1,g(0)=3,g(1)=4,g(2)=5,g(4)=3. Evaluate(a)f(g(2)),(b)g(f(0)),(c)(f∘g)(0),(d)(g∘f)(6),(e)(g∘g)(−2),(f)(f∘f)(4),explaining any undefined result.'),[('(a)2→5→4;(b)0→0→3;(c)0→3→0.','(a)2→5→4;(b)0→0→3;(c)0→3→0.'),('(d)f(6)=6은 g의 정의역 밖이다.(e)−2→1→4;(f)4→2→−2.','(d)f(6)=6 lies outside g’s domain.(e)−2→1→4;(f)4→2→−2.')],('(a)4,(b)3,(c)0,(d)정의되지 않음,(e)4,(f)−2.','(a)4,(b)3,(c)0,(d)undefined,(e)4,(f)−2.'),('f의 두 번째 선분은2x−6이며 이를 이용해 f(5)=4,f(3)=0,f(6)=6,f(4)=2를 확인했다.','The second segment of f is2x−6,verifying f(5)=4,f(3)=0,f(6)=6,f(4)=2.'),list('abcdef'))
D.fig(57,[panel('f red; g blue',(-4.5,6.5,-3,7),[{'points':[(0,0),(2,-2),(6,6)],'color':'#dc2626'},{'points':[(-4,3),(-3,1.5),(-2,1),(-1,1.5),(0,3),(1,4),(2,5),(3,4.7),(4,3)],'color':'#1d4ed8'}],xticks=list(range(-4,7)),yticks=list(range(-2,7)))],('f는 정확한 선분, g는 원본 판독값과 정의역을 보존한 개략도.','f is drawn with exact segments;g is a schematic preserving the source readings and domain.'))
greads=[-.2,1.2,2.2,2.8,3,2.8,2.2,1.2,-.2,-2,-4.2];fgreads=[-4,-3.3,-1.8,-.7,-.3,-.7,-1.8,-3.3,-4,-2.2,2]
add(58,('제시된 두 그래프에서 x=−5,−4,…,5의 f(g(x))를 추정하고 합성함수의 개략 그래프를 그려라. 파랑 g의 근삿값은 순서대로 '+str(greads)+'이다.','Estimate f(g(x)) at x=−5,−4,…,5 from the supplied graphs,and sketch the composition. The blue g has approximate readings '+str(greads)+' in that order.'),[('먼저 각 x에서 g의 높이를 읽은 뒤 그 수를 빨강 f의 수평 입력으로 사용한다.','First read g’s height at each x,then use that value as the horizontal input to red f.'),('예를 들어 g(−1)≈3이고 f(3)≈−0.3이다. g(5)≈−4.2에서는 f(−4.2)≈2.0이다.','For example,g(−1)≈3 and f(3)≈−0.3. At g(5)≈−4.2,the outer reading is f(−4.2)≈2.0.')],('x=−5,…,5 순서의 근삿값 '+str(fgreads)+'.','Approximate values for x=−5,…,5,in order: '+str(fgreads)+'.'),('총괄과 독립 격자 판독을 대조하여 대략±0.2 수준으로 일치했다. 주어지지 않은 함수식을 추정해 정확한 식으로 취급하지 않았다.','Independent grid readings agreed to approximately±0.2. No inferred formula was treated as an exact source function.'))
D.fig(58,[panel('Estimated composition f(g(x))',(-5,5,-4.5,2.5),[list(zip(range(-5,6),fgreads))],list(zip(range(-5,6),fgreads)),xticks=list(range(-5,6)))],('도해 판독값을 잇는 합성함수 개략도; 측정 사이 곡률은 결정되지 않는다.','Composition schematic joining graph-reading estimates;curvature between samples is not determined.'))
add(59,('돌을 호수에 떨어뜨린 뒤 원형 파문이60 cm/s로 퍼진다. (a)시간 t초의 반지름 r(t),(b)넓이 함수 A와 A∘r 및 의미를 구하라.','A circular ripple expands at60 cm/s after a stone enters a lake. Find(a) radius r(t) after t seconds,and(b) area function A,the composition A∘r,and its meaning.'),[('처음 반지름0이므로 r(t)=60t이다. 원의 넓이는 A(r)=πr²이다.','Starting at radius zero gives r(t)=60t. Circle area is A(r)=πr².'),(d(r'(A\circ r)(t)=\pi(60t)^2=3600\pi t^2,\quad t\ge0'),d(r'(A\circ r)(t)=\pi(60t)^2=3600\pi t^2,\quad t\ge0'))],('(a)r(t)=60t cm.(b)3600πt² cm²:시간에 따른 파문 내부 넓이.','(a)r(t)=60t cm.(b)3600πt² cm²:area enclosed by the ripple as a function of time.'),('1초 후 반지름60 cm의 넓이3600π cm²가 나오며 시간2배이면 넓이4배이다.','At1 second radius60 gives area3600π cm²;doubling time quadruples area.'),list('ab'))
add(60,('구형 풍선의 반지름이2 cm/s로 증가한다. (a)r(t),(b)V(r)와 V∘r 및 의미를 구하라.','A spherical balloon’s radius grows at2 cm/s. Find(a)r(t),and(b)V(r),V∘r,and its meaning.'),[('초기 반지름을 r₀라 하면 r(t)=r₀+2t이다. 교재의 통상적인 시작점 r₀=0을 택하면 r(t)=2t이다.','With initial radius r₀,r(t)=r₀+2t. Under the usual zero-radius starting convention,r(t)=2t.'),(d(r'V(r)=\frac43\pi r^3,\quad(V\circ r)(t)=\frac{32}3\pi t^3\quad(r_0=0)'),d(r'V(r)=\frac43\pi r^3,\quad(V\circ r)(t)=\frac{32}3\pi t^3\quad(r_0=0)'))],('(a)r=2t,(b)V∘r=32πt³/3 cm³(초기반지름0). 일반적으로4π(r₀+2t)³/3이며 시간에 따른 부피이다.','(a)r=2t,(b)V∘r=32πt³/3 cm³ if initial radius is zero. Generally it is4π(r₀+2t)³/3,the volume as a function of time.'),('반지름 증가율만으로 초기 반지름을 결정할 수 없으므로 가정을 명시했다. 구 부피식에 직접 대입하여 계수를 확인했다.','A growth rate alone does not determine initial radius,so the assumption is stated. Direct substitution into sphere volume checks the coefficient.'),list('ab'))
add(61,('배는 직선 해안에서6 km 떨어져 평행하게30 km/h로 이동하며 정오에 등대의 최근접점을 지난다. (a)이후 이동거리 d에 따른 등대거리 s=f(d),(b)t시간의 d=g(t),(c)f∘g와 의미를 구하라.','A ship moves parallel to a straight shore,6 km offshore,at30 km/h,and passes the point nearest a lighthouse at noon. Find(a)s=f(d) in terms of distance traveled since noon,(b)d=g(t) for t hours,(c)f∘g and its meaning.'),[('수직거리6과 해안평행 거리d가 직각삼각형을 이룬다.','The perpendicular distance6 and along-shore distance d form a right triangle.'),(d(r'f(d)=\sqrt{d^2+36},\quad g(t)=30t'),d(r'f(d)=\sqrt{d^2+36},\quad g(t)=30t'))],d(r'(f\circ g)(t)=\sqrt{900t^2+36}\ \mathrm{km},\quad t\ge0'),('t=0에서 거리6 km이고 이후 증가한다. 합성은 정오 후 시간에 따른 등대-배 거리이다.','At t=0 the distance is6 km and increases thereafter. The composition gives lighthouse-to-ship distance after noon.'),list('abc'))
add(62,('고도1 mile의 비행기가350 mi/h로 날아 t=0에 레이더 바로 위를 지난다. (a)t시간 후 수평거리 d,(b)d에 따른 레이더거리 s,(c)s(t)를 합성으로 구하라.','A plane at altitude1 mile flies at350 mi/h and passes directly above a radar at t=0. Find(a)horizontal distance d after t hours,(b)radar distance s in terms of d,(c)s(t) by composition.'),[('수평거리 d=350t이며 높이1과 피타고라스 정리를 적용한다.','Horizontal distance is d=350t;apply the Pythagorean theorem with height1.')],d(r'(a)\ d(t)=350t;\quad(b)\ s(d)=\sqrt{d^2+1};\quad(c)\ s(t)=\sqrt{122500t^2+1},\ t\ge0'),('t=0에서1 mile이고,s²−d²=1로 일정한 고도를 확인한다.','At t=0 the distance is1 mile,and s²−d²=1 verifies constant altitude.'),list('abc'))
add(63,('H(t)=0(t<0),H(t)=1(t≥0)이다. (a)H의 그래프,(b)t=0부터120 V를 즉시 가하는 전압,(c)t=5부터240 V를 즉시 가하는 전압을 그리고 H로 표현하라.','Let H(t)=0 for t<0 and1 for t≥0. Sketch(a)H,(b)voltage switched instantly to120 V at t=0,(c)voltage switched instantly to240 V at t=5,and express each using H.'),[('시작시각 s는 H(t−s)로, 전압 크기 A는 AH(t−s)로 표현한다.','A starting time s is encoded by H(t−s),and voltage level A by AH(t−s).')],d(r'(a)\ H(t);\quad(b)\ V(t)=120H(t);\quad(c)\ V(t)=240H(t-5)'),('H(0)=1이므로 전환시각에서 높은 쪽 닫힌 점, 낮은 쪽 열린 점을 사용한다.','Since H(0)=1,the high value is filled at the switching time and the low value is open.'),list('abc'))
D.fig(63,[panel(title,(-2,10,-.1*A,1.2*A),[[(-2,0),(start,0)],[(start,A),(10,A)]],[(start,0,'open'),(start,A)],xlabel='s',ylabel=unit)for title,start,A,unit in [('(a) Heaviside',0,1,'H'),('(b) 120V at0',0,120,'V'),('(c) 240V at5',5,240,'V')]])
add(64,('H는 앞 문항의 계단함수이다. (a)y=tH(t)를 그리고,(b)t=0부터60초 동안0→120 V,(c)t=7부터25초 동안0→100 V로 선형 증가하는 전압을 각각 t≤60,t≤32 범위에서 H로 표현하고 그려라.','With the preceding Heaviside H,sketch(a)y=tH(t);(b)a linear0-to-120 V increase over60 seconds starting at0,for t≤60;(c)a linear0-to-100 V increase over25 seconds starting at7,for t≤32. Express the voltages using H.'),[('램프는 시작 전0이고 시작 후 경과시간에 일정 기울기를 곱한다.','A ramp is zero before switching and equals a constant slope times elapsed time afterward.'),('(b)기울기120/60=2,(c)100/25=4이며(c)의 경과시간은 t−7이다.','The slopes are2 in(b) and4 in(c);elapsed time in(c) is t−7.')],d(r'(a)\ tH(t);\quad(b)\ 2tH(t),\ t\le60;\quad(c)\ 4(t-7)H(t-7),\ t\le32'),('V(60)=120,V(7)=0,V(32)=100이다. 지정된 종료시간 이후 동작은 원문 조건에서 정해지지 않는다.','V(60)=120,V(7)=0,V(32)=100. The source does not specify behavior after the stated end times.'),list('abc'))
D.fig(64,[panel('(a) Unit ramp',(-2,5,-.5,6),[[(-2,0),(0,0),(5,5)]]),panel('(b) 2V per second',(-5,60,-10,130),[[(-5,0),(0,0),(60,120)]],xlabel='s',ylabel='V'),panel('(c) 4V per second from7s',(0,32,-10,110),[[(0,0),(7,0),(32,100)]],xlabel='s',ylabel='V')])
add(65,('f(x)=m₁x+b₁,g(x)=m₂x+b₂가 일차형 함수이다. f∘g도 일차형인지, 기울기는 무엇인지 구하라.','For affine functions f(x)=m₁x+b₁ and g(x)=m₂x+b₂,determine whether f∘g is affine and find its slope.'),[(d(r'f(g(x))=m_1(m_2x+b_2)+b_1=m_1m_2x+m_1b_2+b_1'),d(r'f(g(x))=m_1(m_2x+b_2)+b_1=m_1m_2x+m_1b_2+b_1'))],('일차형이며 기울기 m₁m₂,절편 m₁b₂+b₁이다. 기울기0이면 상수함수라는 퇴화 경우를 포함한다.','It is affine with slope m₁m₂ and intercept m₁b₂+b₁,including the constant case when the slope is zero.'),('입력 증가 Δx가 g에서 m₂Δx, f에서 다시 m₁배가 되어 총 변화 m₁m₂Δx이다.','An input change Δx becomes m₂Δx under g and then m₁ times that under f,confirming the product slope.'))
add(66,('연4% 복리 모형 A(x)=1.04x의 A∘A,3중합성,4중합성을 구하고 의미와 n중합성의 일반식을 제시하라.','For annual4% compounding A(x)=1.04x,find A∘A,the triple and quadruple compositions,interpret them,and give the n-fold formula.'),[('합성 한 번마다 남은 금액 전체에1.04를 다시 곱한다.','Each additional composition multiplies the entire balance by1.04 again.')],d(r'A^{\circ2}(x)=1.0816x,\quad A^{\circ3}(x)=1.124864x,\quad A^{\circ4}(x)=1.16985856x,\quad A^{\circ n}(x)=1.04^nx'),('각각2,3,4,n년 뒤 금액이다. n년 금액에1.04를 곱하면 n+1년 식이 되어 귀납적으로 확인된다.','These are balances after2,3,4,n years. Multiplying the n-year formula by1.04 gives the(n+1)-year formula,verifying it inductively.'))
add(67,('(a)g(x)=2x+1,h(x)=4x²+4x+7일 때 f∘g=h인 f,(b)f(x)=3x+5,h(x)=3x²+3x+2일 때 f∘g=h인 g를 구하라.','Find(a)f with f∘g=h when g(x)=2x+1,h(x)=4x²+4x+7;(b)g with f∘g=h when f(x)=3x+5,h(x)=3x²+3x+2.'),[('(a)h(x)=(2x+1)²+6이므로 f(u)=u²+6이다.','(a)Since h(x)=(2x+1)²+6,take f(u)=u²+6.'),('(b)3g(x)+5=h(x)를 풀면 g(x)=(h(x)−5)/3이다.','(b)Solving3g(x)+5=h(x) gives g(x)=(h(x)−5)/3.')],d(r'(a)\ f(x)=x^2+6;\qquad(b)\ g(x)=x^2+x-1'),('두 답을 각각 합성하면4x²+4x+7과3x²+3x+2가 직접 복원된다.','Substitution into the compositions restores4x²+4x+7 and3x²+3x+2.'),list('ab'))
add(68,('f(x)=x+4,h(x)=4x−1일 때 g∘f=h인 g를 구하라.','Find g with g∘f=h for f(x)=x+4 and h(x)=4x−1.'),[('u=x+4라 두면 x=u−4이고 g(u)=4(u−4)−1이다.','Set u=x+4,so x=u−4 and g(u)=4(u−4)−1.')],d('g(x)=4x-17'),('g(f(x))=4(x+4)−17=4x−1이다.','g(f(x))=4(x+4)−17=4x−1.'))
add(69,('g가 짝함수이고 h=f∘g일 때 h는 항상 짝함수인가?','If g is even and h=f∘g,is h necessarily even?'),[(d(r'h(-x)=f(g(-x))=f(g(x))=h(x)'),d(r'h(-x)=f(g(-x))=f(g(x))=h(x)')),('합성이 정의되는 입력 집합도 g(−x)=g(x) 때문에 원점 대칭이다.','The composition’s domain is symmetric because g(−x)=g(x).')],('그렇다. 합성이 정의되는 대칭 정의역에서 짝함수이다.','Yes,on the symmetric domain where the composition is defined.'),('f에는 대칭 조건이 필요 없으며 g의 출력이 같다는 사실만 사용했다.','No parity condition on f is needed;only equality of the inner outputs was used.'))
add(70,('g가 홀함수이고 h=f∘g이다. h가 항상 홀함수인지, f도 홀함수일 때와 f가 짝함수일 때를 각각 판단하라.','Let g be odd and h=f∘g. Is h always odd? What happens if f is odd,or if f is even?'),[('일반적으로는 아니다. g(x)=x,f(u)=u²이면 h=x²로 홀함수가 아니다.','Not in general:take g(x)=x and f(u)=u²,so h=x² is not odd.'),(d(r'h(-x)=f(-g(x))'),d(r'h(-x)=f(-g(x))')),('f가 홀수이면−f(g(x))이므로 h는 홀수, f가 짝수이면 f(g(x))이므로 h는 짝수이다. 이 경우 합성 정의역도 대칭이다.','If f is odd this equals−f(g(x)),so h is odd. If f is even it equals f(g(x)),so h is even. In either case the composition domain is symmetric.')],('일반적으로 아님; f홀수이면 h홀수; f짝수이면 h짝수.','Not generally;if f is odd,h is odd;if f is even,h is even.'),('홀수 예 x³∘x=x³,짝수 예 x²∘x=x²로 부호 규칙을 대조했다.','The examples x³∘x=x³ and x²∘x=x² confirm the sign rules.'))
add(71,('정의역ℝ인 f에 대해(a)E(x)=f(x)+f(−x)가 짝함수,(b)O(x)=f(x)−f(−x)가 홀함수임을 보이고,(c)f를 짝수+홀수로 분해하라.(d)f(x)=2ˣ+(x−3)²에 적용하라.','For f onℝ,show(a)E(x)=f(x)+f(−x) is even,(b)O(x)=f(x)−f(−x) is odd,(c)decompose f as even plus odd,and(d)apply this to f(x)=2ˣ+(x−3)².'),[(d(r'E(-x)=f(-x)+f(x)=E(x),\quad O(-x)=f(-x)-f(x)=-O(x)'),d(r'E(-x)=f(-x)+f(x)=E(x),\quad O(-x)=f(-x)-f(x)=-O(x)')),(d(r'f(x)=\frac{f(x)+f(-x)}2+\frac{f(x)-f(-x)}2'),d(r'f(x)=\frac{f(x)+f(-x)}2+\frac{f(x)-f(-x)}2')),('예제에서는 (x−3)²=x²−6x+9,(-x−3)²=x²+6x+9를 사용한다.','For the example,use(x−3)²=x²−6x+9 and(−x−3)²=x²+6x+9.')],d(r'f(x)=\underbrace{\frac{2^x+2^{-x}}2+x^2+9}_{\text{even}}+\underbrace{\frac{2^x-2^{-x}}2-6x}_{\text{odd}}'),('두 성분을 더하면2⁻ˣ 항이 상쇄되어 원식이 복원되며 x→−x에서 각각 같은값·반대값을 갖는다.','Adding the components cancels the2⁻ˣ terms and restores f;replacing x by−x preserves the first and negates the second.'),list('abcd'))
base3=[(0,1),(.7,2.5),(1.35,3),(2,2.5),(3,0)]
trans3=[('f',lambda a,b:(a,b)),('1',lambda a,b:(a,b+3)),('2',lambda a,b:(a-6,2*b)),('3',lambda a,b:(a+4,b)),('4',lambda a,b:(a,b/3)),('5',lambda a,b:(a-4,-b))]
D.fig(3,[panel('Graph '+label,(-7,8,-4,7),[[fn(a,b)for a,b in base3]],xticks=[-6,-3,0,3,6],yticks=[-3,0,3,6])for label,fn in trans3],('원본의 위치·최고 높이·변환 대응을 보존한 자체 개략도.','Original schematic preserving source positions,peak heights,and transformation relationships.'))
D.save(71)
